mapper.select:
SELECT entrustId, entrustStatus, portfolioId, portfolioName, assetType1,
assetType10, assetType11,
finprodMarketId, finprodId,
finprodAbbr,
ps, ccy, vdate, mdate, entrustAmt, entrustNum, finishAmt, transactioncom, trmFundType, tradeMarket FROM (select ETR_ENTRUST.ENTRUST_ID entrustId, ETR_ENTRUST.ENTRUST_STATUS entrustStatus, ETR_ENTRUST.PORTFOLIO_ID portfolioId, PTL_PORTFOLIO.PORTFOLIO_NAME portfolioName, ETR_ENTRUST_ADD.ASSET_TYPE1 assetType1,
ETR_ENTRUST_ADD.ASSET_TYPE_10 assetType10, ETR_ENTRUST_ADD.ASSET_TYPE_11 assetType11,
FIN_PRODUCT.FINPROD_MARKET_ID finprodMarketId, FIN_PRODUCT.FINPROD_ID finprodId,
FIN_PRODUCT.FINPROD_ABBR finprodAbbr,
ETR_ENTRUST.PS ps, ETR_ENTRUST.CCY ccy, ETR_ENTRUST.VDATE vdate, ETR_ENTRUST.MDATE mdate, ETR_ENTRUST.ENTRUST_AMT entrustAmt, ETR_ENTRUST.ENTRUST_NUM entrustNum, FIN_PRODUCT_ADD.TRM_FUND_TYPE trmFundType, FIN_PRODUCT.TRADE_MARKET tradeMarket, nvl(ETR_FINISH_STATUS_A.FINISH_AMT,0) finishAmt, round(ETR_FINISH_STATUS_A.FINISH_AMT/NVL(ETR_ENTRUST.ENTRUST_AMT,cast(ETR_ENTRUST.ENTRUST_NUM as decimal(30,2))),2)*100 transactioncom from ETR_ENTRUST left join PTL_PORTFOLIO on PTL_PORTFOLIO.PORTFOLIO_ID = ETR_ENTRUST.PORTFOLIO_ID
inner join FIN_PRODUCT on FIN_PRODUCT.FINPROD_ID = ETR_ENTRUST.FINPROD_ID inner join FIN_PRODUCT_ADD on FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID inner join ETR_ENTRUST_ADD on ETR_ENTRUST_ADD.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID left join (select ENTRUST_ID,sum(nvl(FINISH_AMT,0)) as FINISH_AMT from ETR_FINISH_STATUS group by ENTRUST_ID) ETR_FINISH_STATUS_A on ETR_FINISH_STATUS_A.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID INNER JOIN PTL_PORTFOLIO_AUTHORITY ON PTL_PORTFOLIO.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID AND PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userId}
AND (PTL_PORTFOLIO.PORTFOLIO_ID IN
#{prot}
or PTL_PORTFOLIO.PARENT_PORTFOLIO_ID IN
#{prot}
)
AND ETR_ENTRUST_ADD.ASSET_TYPE1 IN
#{item,jdbcType=VARCHAR}
AND ETR_ENTRUST_ADD.ASSET_TYPE_10 IN
#{item,jdbcType=VARCHAR}
AND ETR_ENTRUST_ADD.ASSET_TYPE_11 IN
#{item,jdbcType=VARCHAR}
AND ETR_ENTRUST.CCY = #{ccy,jdbcType=VARCHAR}
AND ETR_ENTRUST.PS IN
#{item,jdbcType=VARCHAR}
AND ETR_ENTRUST.ENTRUST_STATUS = #{entrustStatus,jdbcType=VARCHAR}
AND ETR_ENTRUST.VDATE >= #{startDate,jdbcType=DATE}
AND ETR_ENTRUST.MDATE <= #{endDate,jdbcType=DATE}
AND (FIN_PRODUCT.FINPROD_MARKET_ID like concat('%',concat(#{finprodId,jdbcType=VARCHAR},'%')) OR FIN_PRODUCT.FINPROD_NAME like concat('%',concat(#{finprodId,jdbcType=VARCHAR},'%')) )
AND FIN_PRODUCT.FINPROD_TYPE2 = #{finprodType2,jdbcType=VARCHAR}
AND FIN_PRODUCT_ADD.TRM_FUND_TYPE = #{trmFundType,jdbcType=VARCHAR}
AND FIN_PRODUCT.TRADE_MARKET = #{tradeMarket,jdbcType=VARCHAR}
union all select ETR_ENTRUST.ENTRUST_ID entrustId, ETR_ENTRUST.ENTRUST_STATUS entrustStatus, ETR_ENTRUST.PORTFOLIO_ID portfolioId, PTL_PORTFOLIO.PORTFOLIO_NAME portfolioName, ETR_ENTRUST_ADD.ASSET_TYPE1 assetType1,
ETR_ENTRUST_ADD.ASSET_TYPE_10 assetType10, ETR_ENTRUST_ADD.ASSET_TYPE_11 assetType11,
NULL finprodMarketId, NULL finprodId, NULL finprodName, ETR_ENTRUST.PS ps, ETR_ENTRUST.CCY ccy, ETR_ENTRUST.VDATE vdate, ETR_ENTRUST.MDATE mdate, ETR_ENTRUST.ENTRUST_AMT entrustAmt, ETR_ENTRUST.ENTRUST_NUM entrustNum, NULL trmFundType, NULL tradeMarket, nvl(ETR_FINISH_STATUS_A.FINISH_AMT,0) finishAmt, round(ETR_FINISH_STATUS_A.FINISH_AMT/NVL(ETR_ENTRUST.ENTRUST_AMT,cast(ETR_ENTRUST.ENTRUST_NUM as decimal(30,2))),2)*100 transactioncom from ETR_ENTRUST left join PTL_PORTFOLIO on PTL_PORTFOLIO.PORTFOLIO_ID = ETR_ENTRUST.PORTFOLIO_ID
inner join ETR_ENTRUST_ADD on ETR_ENTRUST_ADD.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID left join (select ENTRUST_ID,sum(nvl(FINISH_AMT,0)) as FINISH_AMT from ETR_FINISH_STATUS group by ENTRUST_ID) ETR_FINISH_STATUS_A on ETR_FINISH_STATUS_A.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID INNER JOIN PTL_PORTFOLIO_AUTHORITY ON PTL_PORTFOLIO.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID AND PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userId}
AND (PTL_PORTFOLIO.PORTFOLIO_ID like concat('%',concat(#{portfolioId,jdbcType=VARCHAR},'%')) OR PTL_PORTFOLIO.PORTFOLIO_NAME like concat('%',concat(#{portfolioId,jdbcType=VARCHAR},'%')) )
AND ETR_ENTRUST_ADD.ASSET_TYPE1 IN
#{item,jdbcType=VARCHAR}
AND ETR_ENTRUST_ADD.ASSET_TYPE_10 IN
#{item,jdbcType=VARCHAR}
AND ETR_ENTRUST_ADD.ASSET_TYPE_11 IN
#{item,jdbcType=VARCHAR}
AND ETR_ENTRUST.CCY = #{ccy,jdbcType=VARCHAR}
AND ETR_ENTRUST.PS IN
#{item,jdbcType=VARCHAR}
AND ETR_ENTRUST.ENTRUST_STATUS = #{entrustStatus,jdbcType=VARCHAR}
AND ETR_ENTRUST.VDATE >= #{startDate,jdbcType=DATE}
AND ETR_ENTRUST.MDATE <= #{endDate,jdbcType=DATE}
AND ETR_ENTRUST.FINPROD_TYPE2 = #{finprodType2,jdbcType=VARCHAR} AND NOT EXISTS (SELECT 1 FROM FIN_PRODUCT WHERE FIN_PRODUCT.FINPROD_ID = ETR_ENTRUST.FINPROD_ID)
) order by entrustId desc
